const pendingChanges = $input.all();

// *** CRITICAL FIX: Ensure this URL matches your POST webhook's PRODUCTION path ***
const postUrl = "http://localhost:5678/webhook/approval-dashboard"; 

// Helper function to safely escape HTML special characters
function safe(s) {
  if (s === null || s === undefined) return '';
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;'); // Use HTML entity for single quotes
}

let html = `
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Approval Dashboard</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Roboto:wght@400;500;700&display=swap" rel="stylesheet"><style>body{font-family:'Roboto',sans-serif;background-color:#f0f2f5;color:#333;margin:0;padding:2em;}.container{max-width:900px;margin:0 auto;}header{background-color:#ffffff;padding:1.5em 2em;border-radius:10px;box-shadow:0 4px 6px rgba(0,0,0,0.05);margin-bottom:2em;}header h1{margin:0;color:#1a2c4e;font-size:1.8em;}.procedure{background-color:#ffffff;border:1px solid #e0e0e0;border-radius:10px;padding:1.5em;margin-bottom:1.5em;box-shadow:0 4px 6px rgba(0,0,0,0.05);transition:transform 0.2s ease-in-out;}.procedure:hover{transform:translateY(-5px);}.procedure-header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #eee;padding-bottom:1em;margin-bottom:1em;}.procedure-header h3{margin:0;font-family:monospace;font-size:1.2em;color:#0d1b2a;}.change-type{background-color:#e7f3ff;color:#005fcc;padding:0.3em 0.8em;border-radius:15px;font-size:0.8em;font-weight:500;}pre{background-color:#f8f9fa;padding:1em;white-space:pre-wrap;border:1px solid #e0e0e0;border-radius:5px;font-family:monospace;font-size:0.9em;line-height:1.5;}.actions{margin-top:1.5em;text-align:right;}button{padding:0.7em 1.5em;border:none;border-radius:5px;cursor:pointer;font-size:0.9em;font-weight:500;transition:background-color 0.2s;margin-left:0.5em;}.approve{background-color:#28a745;color:white;}.approve:hover{background-color:#218838;}.reject{background-color:#dc3545;color:white;}.reject:hover{background-color:#c82333;}</style></head><body><div class="container"><header><h1>Pending Procedure Approvals</h1></header>
`;

if (pendingChanges.length === 0) {
    html += '<div class="procedure"><p>✅ No pending changes to review.</p></div>';
} else {
    for (const item of pendingChanges) {
        const data = item.json;
        // Safely get definition and check if change is DELETED
        const encodedDefinition = safe(data.dev_definition); 
        const changes = safe(data.changes_only || 'No diff details available.');
        const isDeleted = data.change_type === 'DELETED';

        html += `
            <div class="procedure">
                <div class="procedure-header">
                    <h3>${safe(data.procedure_name)}</h3>
                    <span class="change-type">${safe(data.change_type)}</span>
                </div>
                <pre>${changes}</pre>
                <div class="actions">
                    <form action="${postUrl}" method="POST" style="display:inline;">
                        <input type="hidden" name="procedure_name" value="${safe(data.procedure_name)}">
                        <input type="hidden" name="decision" value="reject">
                        <button type="submit" class="reject">Reject</button>
                    </form>
                    <form action="${postUrl}" method="POST" style="display:inline;">
                        <input type="hidden" name="procedure_name" value="${safe(data.procedure_name)}">
                        <input type="hidden" name="decision" value="approve">
                        <input type="hidden" name="dev_definition" value='${encodedDefinition}'>
                        <button type="submit" class="approve" ${isDeleted ? 'disabled' : ''}>Approve</button>
                    </form>
                </div>
            </div>`;
    }
}
html += '</div></body></html>';

return { htmlResponse: html };

