// Get the data from the SPECIFIC previous nodes by their names
const devDefinitionData = $items("Get Dev Definition")[0].json; 
const changeTypeData = $items("Get Change Type")[0].json;

// Extract the values
const definition = devDefinitionData.dev_definition_latest;
const changeType = changeTypeData.change_type;

let deploySql = definition; // Default to the original definition (CREATE)

// If the change type is MODIFIED, change CREATE to ALTER
if (changeType === 'MODIFIED' && definition) {
  // Use a case-insensitive regex to replace the first occurrence of CREATE PROCEDURE
  deploySql = definition.replace(/^(\s*)CREATE(\s+)PROCEDURE/i, '$1ALTER$2PROCEDURE');
} else if (changeType === 'NEW' && definition) {
  // Ensure NEW procedures also use the fetched definition
  deploySql = definition; 
} else {
  // Handle cases where definition might be missing or changeType is unexpected
  console.error("Could not prepare deploy SQL. ChangeType:", changeType, "Definition available:", !!definition);
  deploySql = null; // Prevent deploying invalid SQL
}

// Return the final SQL command (or null if there was an issue)
if (deploySql) {
  return {
    json: {
      deploySql: deploySql
    }
  };
} else {
  // If deploySql is null, return nothing to stop the 'Deploy' node
  return []; 
}

// Get the procedure name from the IF node (adjust name if needed)
// *** THIS IS THE CRITICAL CHANGE ***
const procedureName = $items("If")[0].json.procedure_name || 'unknown procedure';

console.log("Deploy to Production node finished for:", procedureName);

// Get the output from the Deploy node (which is the input to this node)
const deployOutput = $input.item.json; 
console.log("Deploy Output:", deployOutput); 

// Add the procedureName to the output for the next node
deployOutput.procedure_name = procedureName; 

// Pass the combined data along
return deployOutput;

// lg1 Code Node (after IF false)
console.log("REJECT path started for procedure:", $input.item.json.procedure_name);

// Pass the incoming data directly to the next node
return $input.item.json;

